constraints:
1 <= |str| <= 10^{4}

expected time complexity: O(n)
expected auxiliary space: O(n) where n  = |str|

standard_solution_code:
class Solution:

	def CountWays(self, st):
		di = {x: 1 for x in range(1, 27)}
		m = 1000000007
		li = [1]
		if st[0] == '0':
			return 0
		li.append(1)
		for i in range(1, len(st)):
			if st[i] == '0':
				if st[i - 1] == '1' or st[i - 1] == '2':
					x = li[-2] % m
					li.append(x)
				else:
					return 0
			else:
				x = int(str[i])
				y = int(str[i - 1:i + 1])
				if y == x or y not in di.keys():
					n = li[-1] % m
					li.append(n)
				else:
					li.append((li[-1] % m + li[-2] % m) % m)
		return li[-1] % m
